#pragma once

#include "CoreMinimal.h"

/**
 * The sound a client plays when the server saved a blueprint.
 *
 * Public builds ship S_BXSave, a chime generated by SourceArt/Audio/build_save_sound.py (our own
 * work, decision D-007). A personal build may add /BlueprintX/Audio/Personal/S_BXSavePersonal;
 * when that asset exists it plays instead. The Personal folder is never committed or shipped.
 */
class BLUEPRINTX_API FBXSaveSound
{
public:
	/** Client side; plain Unreal audio (USoundWave), no Wwise event. */
	static void Play(const UObject* WorldContext);
};
